SET GLOBAL tidb_enable_check_constraint = ON;
SET GLOBAL tidb_ddl_enable_fast_reorg = OFF;
DROP DATABASE IF EXISTS d1; DROP DATABASE IF EXISTS `d<2>&`; DROP DATABASE IF EXISTS d3;
DROP PLACEMENT POLICY IF EXISTS p1; DROP PLACEMENT POLICY IF EXISTS p2;
DROP RESOURCE GROUP IF EXISTS rg1; DROP RESOURCE GROUP IF EXISTS rg2; DROP RESOURCE GROUP IF EXISTS rg3;
CREATE DATABASE d1 CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
CREATE DATABASE `d<2>&` CHARACTER SET gbk;
CREATE PLACEMENT POLICY p1 PRIMARY_REGION="r1" REGIONS="r1,r2" FOLLOWERS=2;
CREATE PLACEMENT POLICY p2 CONSTRAINTS='[+disk=ssd]' LEADER_CONSTRAINTS='[+region=us]' LEARNERS=1 SURVIVAL_PREFERENCES='[zone]';
CREATE DATABASE d3;
CREATE RESOURCE GROUP rg1 RU_PER_SEC=1000 PRIORITY=HIGH BURSTABLE;
CREATE RESOURCE GROUP rg2 RU_PER_SEC=500 QUERY_LIMIT=(EXEC_ELAPSED='10s' ACTION=KILL WATCH=SIMILAR DURATION='1m');
CREATE RESOURCE GROUP rg3 RU_PER_SEC=100 QUERY_LIMIT=(EXEC_ELAPSED='5s' PROCESSED_KEYS=100 ACTION=SWITCH_GROUP(rg1));
ALTER RESOURCE GROUP default BACKGROUND=(TASK_TYPES='br,lightning' UTILIZATION_LIMIT=30);
USE d1;
CREATE TABLE t_types (
  c_tiny TINYINT(3) UNSIGNED ZEROFILL DEFAULT 1, c_small SMALLINT DEFAULT -2, c_med MEDIUMINT, c_int INT NOT NULL DEFAULT 42,
  c_big BIGINT UNSIGNED DEFAULT 18446744073709551615, c_float FLOAT(7,3) DEFAULT 1.5, c_double DOUBLE DEFAULT 1e-7,
  c_dec DECIMAL(65,30) DEFAULT 123.456, c_dec2 DECIMAL(20,0) DEFAULT 99999999999999999999,
  c_date DATE DEFAULT '2024-02-29', c_dt DATETIME(6) DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  c_ts TIMESTAMP(3) NULL DEFAULT NULL, c_time TIME(2) DEFAULT '-838:59:59', c_year YEAR DEFAULT 2155,
  c_char CHAR(10) CHARACTER SET latin1 DEFAULT 'a<b>&c', c_vc VARCHAR(255) COLLATE utf8mb4_bin DEFAULT '日本語',
  c_bin BINARY(4) DEFAULT 0x00ff, c_vbin VARBINARY(10), c_text TEXT, c_blob LONGBLOB, c_tt TINYTEXT, c_mt MEDIUMTEXT CHARACTER SET gbk,
  c_bit BIT(10) DEFAULT b'1010101010', c_bit1 BIT(1) DEFAULT 1, c_enum ENUM('x','y''q','z\\n', 0xff) DEFAULT 'y''q',
  c_set SET('a','b','c') DEFAULT 'a,c', c_json JSON, c_vec VECTOR(3), c_vec2 VECTOR,
  c_gen_v INT AS (c_int + 1) VIRTUAL, c_gen_s VARCHAR(20) AS (UPPER(c_char)) STORED COMMENT 'generated "stored"',
  c_bool BOOL DEFAULT TRUE, c_double2 DOUBLE DEFAULT 123456789012345678901234567890,
  PRIMARY KEY (c_int) NONCLUSTERED, UNIQUE KEY uk (c_vc(10), c_char), KEY ix_expr ((c_int * 2)),
  KEY ix_inv (c_small) INVISIBLE, KEY ix_mv ((CAST(c_json->'$.a' AS UNSIGNED ARRAY))), KEY ix_comment (c_med) COMMENT 'idx <>'
) COMMENT='types table' SHARD_ROW_ID_BITS=4 PRE_SPLIT_REGIONS=2;
CREATE TABLE t_auto (id BIGINT AUTO_RANDOM(5, 54) PRIMARY KEY CLUSTERED, v INT) AUTO_RANDOM_BASE=100;
CREATE TABLE t_ai (id INT AUTO_INCREMENT PRIMARY KEY, v INT) AUTO_ID_CACHE 1 AUTO_INCREMENT=1000;
CREATE TABLE t_common (a VARCHAR(10), b INT, PRIMARY KEY (a, b) CLUSTERED);
CREATE TABLE t_range (id INT, d DATE, PRIMARY KEY (id, d)) PARTITION BY RANGE (YEAR(d)) (
  PARTITION p0 VALUES LESS THAN (2000), PARTITION p1 VALUES LESS THAN (2020) COMMENT 'c1',
  PARTITION pmax VALUES LESS THAN (MAXVALUE));
CREATE TABLE t_rcols (a INT, b VARCHAR(10)) PARTITION BY RANGE COLUMNS (a, b) (PARTITION p0 VALUES LESS THAN (10, 'x'), PARTITION p1 VALUES LESS THAN (MAXVALUE, MAXVALUE));
CREATE TABLE t_list (a INT) PARTITION BY LIST (a) (PARTITION p0 VALUES IN (1, 2, NULL), PARTITION p1 VALUES IN (3), PARTITION pd VALUES IN (DEFAULT));
CREATE TABLE t_lcols (a INT, b CHAR(2)) PARTITION BY LIST COLUMNS (a, b) (PARTITION p0 VALUES IN ((1,'a'),(2,'b')), PARTITION p1 VALUES IN ((3,'c')));
CREATE TABLE t_hash (a INT, b INT, UNIQUE KEY (a)) PARTITION BY HASH (a) PARTITIONS 4;
CREATE TABLE t_key (a VARCHAR(10)) PARTITION BY KEY (a) PARTITIONS 3;
CREATE TABLE t_interval (id INT, ts DATETIME) PARTITION BY RANGE COLUMNS (ts) INTERVAL (1 MONTH) FIRST PARTITION LESS THAN ('2024-01-01') LAST PARTITION LESS THAN ('2024-06-01');
CREATE TABLE t_global (a INT, b INT, UNIQUE KEY ug (b) GLOBAL) PARTITION BY HASH (a) PARTITIONS 2;
CREATE TABLE t_parent (id INT PRIMARY KEY, name VARCHAR(20));
CREATE TABLE t_child (id INT PRIMARY KEY, pid INT, CONSTRAINT fk1 FOREIGN KEY (pid) REFERENCES t_parent (id) ON DELETE CASCADE ON UPDATE SET NULL);
CREATE TABLE t_check (a INT CHECK (a > 0), b INT, CONSTRAINT chk_b CHECK (b < 100) NOT ENFORCED);
CREATE TABLE t_ttl (id INT, created_at DATETIME) TTL = created_at + INTERVAL 1 DAY TTL_ENABLE = 'OFF' TTL_JOB_INTERVAL = '2h';
CREATE TABLE t_placed (a INT);
CREATE TABLE t_cache (a INT);
ALTER TABLE t_cache CACHE;
CREATE GLOBAL TEMPORARY TABLE t_temp (a INT) ON COMMIT DELETE ROWS;
CREATE TABLE `表 名` (`列 a` INT, `b``q` VARCHAR(5) COMMENT ' ');
CREATE TABLE t_alter (a INT, b INT, c INT, KEY (b));
ALTER TABLE t_alter ADD COLUMN d INT DEFAULT 7 AFTER a;
ALTER TABLE t_alter MODIFY COLUMN c BIGINT;
ALTER TABLE t_alter DROP COLUMN b;
ALTER TABLE t_alter ADD INDEX ic (c, d);
ALTER TABLE t_alter RENAME INDEX ic TO ic2;
ALTER TABLE t_alter ADD COLUMN e BIT(3) DEFAULT b'101';
ALTER TABLE t_alter CHANGE COLUMN e e2 BIT(3) DEFAULT b'011';
ALTER TABLE t_range ADD PARTITION (PARTITION p2 VALUES LESS THAN (2030));
ALTER TABLE t_range TRUNCATE PARTITION p0;
ALTER TABLE t_list REORGANIZE PARTITION p1 INTO (PARTITION p1a VALUES IN (3), PARTITION p1b VALUES IN (4));
ALTER TABLE t_hash COALESCE PARTITION 2;
CREATE TABLE t_ex (a INT, b INT, UNIQUE KEY (a));
ALTER TABLE t_hash EXCHANGE PARTITION p0 WITH TABLE t_ex;
CREATE TABLE t_np (a INT);
ALTER TABLE t_np PARTITION BY HASH (a) PARTITIONS 2;
CREATE TABLE t_unp (a INT) PARTITION BY HASH (a) PARTITIONS 2;
ALTER TABLE t_unp REMOVE PARTITIONING;
CREATE SEQUENCE s1 START WITH 10 INCREMENT BY -2 MINVALUE -100 MAXVALUE 1000 CACHE 5 CYCLE COMMENT 'seq';
CREATE SEQUENCE s2;
CREATE ALGORITHM=MERGE DEFINER='root'@'%' SQL SECURITY INVOKER VIEW v1 AS SELECT c_int, c_vc FROM t_types WHERE c_int > 1 WITH CASCADED CHECK OPTION;
CREATE VIEW v2 (x, y) AS SELECT 1, 'a<b>';
ALTER TABLE t_types SET TIFLASH REPLICA 0;
ALTER TABLE t_ttl TTL_ENABLE = 'ON';
ALTER TABLE t_types COMMENT = 'α & ω';
ALTER TABLE t_alter AUTO_INCREMENT = 5000;
ALTER TABLE t_common ADD INDEX ia (a(3));
ALTER TABLE t_parent ADD COLUMN extra JSON DEFAULT (JSON_OBJECT('k', 1.5e300, 'n', 12345678901234567890));
CREATE TABLE t_def_expr (a INT, b DATETIME DEFAULT (NOW()), c VARCHAR(36) DEFAULT (UUID()));
CREATE TABLE t_pre_split (id INT PRIMARY KEY NONCLUSTERED) SHARD_ROW_ID_BITS=3 PRE_SPLIT_REGIONS=3;
CREATE TABLE t_charset (a VARCHAR(10) CHARACTER SET ascii, b TEXT CHARACTER SET binary, c CHAR(3) COLLATE utf8mb4_0900_ai_ci, d VARCHAR(3) COLLATE utf8mb4_unicode_ci);
USE `d<2>&`;
CREATE TABLE tg (a VARCHAR(10), b ENUM('一','二')) DEFAULT CHARSET=gbk;
USE d3;
CREATE TABLE tp3 (a INT);
SET GLOBAL tidb_enable_dist_task = OFF;
USE d1;
ALTER TABLE t_alter ADD INDEX ic (c, d);
ALTER TABLE t_alter RENAME INDEX ic TO ic2;
ALTER TABLE t_common ADD INDEX ia (a(3));
ALTER TABLE t_range REORGANIZE PARTITION pmax INTO (PARTITION p2 VALUES LESS THAN (2030), PARTITION pmax VALUES LESS THAN (MAXVALUE));
CREATE TABLE t_def_expr (a INT, b DATETIME DEFAULT (NOW()), c VARCHAR(36) DEFAULT (UUID()));
CREATE TABLE t_tiflash (a INT);
ALTER TABLE t_tiflash SET TIFLASH REPLICA 0;
ALTER TABLE t_parent ADD COLUMN extra2 DOUBLE DEFAULT 1e-300;
